mapper.select:
JOIN host_organizations o ON o.id=a.host_organization_id WHERE a.host_organization_id IS NOT NULL AND a.product_status='ENABLED' AND a.inventory_mode='INTERNAL' AND o.operational_status='ENABLED' AND o.verification_status='VERIFIED' AND (a.place_ref_id IS NULL OR p.lifecycle_status='ACTIVE')
AND (a.title ILIKE CONCAT('%',#{query},'%') OR a.activity_address ILIKE CONCAT('%',#{query},'%'))
AND a.activity_type IN #{t}
ORDER BY a.created_at DESC LIMIT #{limit} OFFSET #{offset}

JOIN host_organizations o ON o.id=a.host_organization_id WHERE a.host_organization_id IS NOT NULL AND a.product_status='ENABLED' AND a.inventory_mode='INTERNAL' AND o.operational_status='ENABLED' AND o.verification_status='VERIFIED' AND (a.place_ref_id IS NULL OR p.lifecycle_status='ACTIVE') AND a.id <> #{excludeId} AND a.activity_type IN #{t} ORDER BY
CASE WHEN a.search_lat IS NULL THEN 1 ELSE 0 END, (a.search_lat-#{lat})*(a.search_lat-#{lat})+(a.search_lng-#{lng})*(a.search_lng-#{lng}),
a.rating DESC NULLS LAST, a.created_at DESC LIMIT #{limit}

 WHERE a.host_organization_id IS NOT NULL
AND a.product_status=#{status}
AND a.title ILIKE CONCAT('%',#{query},'%')
ORDER BY a.created_at DESC LIMIT #{limit} OFFSET #{offset}

